git checkout -- docs/LIBRARY_PLAN.md && cat > "$CLAUDE_JOB_DIR/tmp/plan.js" <<'EOF'
const fs=require("fs");const p="docs/LIBRARY_PLAN.md";
const lines=fs.readFileSync(p,"utf8").split("\n");
for(const n of ["01","04","05","08","10","31"]){
  const d=fs.readdirSync("decks").find(x=>x.startsWith(n+"-"));
  const c=fs.readFileSync("decks/"+d+"/deck.js","utf8").match(/hero: \{ layout: "([^"]+)", concept: "([^"]+)"/);
  const i=lines.findIndex(l=>l.startsWith("| "+n+" |"));
  const cr=lines[i].endsWith("\r")?"\r":"";
  const cells=lines[i].replace(/\r$/,"").split("|");
  if(cells[4].trim()!==c[1]){console.log("layout mismatch",n);continue}
  cells[5]=" "+c[2].replace(/\|/g,"/")+" ";
  lines[i]=cells.join("|")+cr;console.log("ok",n);
}
fs.writeFileSync(p,lines.join("\n"));
EOF
node "$CLAUDE_JOB_DIR/tmp/plan.js" && git diff --stat docs/LIBRARY_PLAN.md && git diff docs/LIBRARY_PLAN.md | grep '^+|' | cut -c1-110

